package ama.transcript;
import ama.minutes.ControlledMinutesTemplateInstaller;import ama.canonical.*;import ama.config.*;import ama.contract.MinutesContracts.*;import ama.minutes.contract.ContractValues;import ama.model.ControlledMinutesProtocol;import java.util.*;
import static ama.canonical.CanonicalValue.*;import static ama.config.WireValues.fields;import static ama.config.WireValues.text;import static ama.config.WireValues.array;import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Pure controlled renderer. Caller data cannot grant a send, source read, or database write. */
public final class ControlledMinutesRenderer {
 private ControlledMinutesRenderer(){}
 public static CanonicalValue.ObjectValue render(List<FullRow> rows,GenerationDraft draft,ConfigBindings.ValidatedGenerationBinding binding){
  require(rows!=null&&rows.size()<=100000,BUDGET_EXCEEDED);var prompt=fields(binding.promptDefinition(),"instructionText");var model=fields(binding.modelDefinition(),"protocolVersion","modelIdentity","credentialRef","parameters");require(text(model.get("protocolVersion")).equals(ControlledMinutesProtocol.VERSION)&&text(model.get("modelIdentity")).equals(ControlledMinutesProtocol.MODEL),CAPABILITY_UNAVAILABLE);ama.config.WireValues.nil(model.get("credentialRef"));var excluded=excluded(binding);var transcript=new ArrayList<CanonicalValue>();
  for(var entry:binding.catalog().sources()){if(!(entry.fact().locator() instanceof TranscriptLocator))continue;if(excluded.contains(ContractValues.locator(entry.fact().locator())))continue;var locator=(TranscriptLocator)entry.fact().locator();var segment=rows.stream().filter(r->r.table()==Table.TRANSCRIPT_SEGMENT&&r.string("revision_id").equals(locator.transcriptRevisionId())&&r.string("segment_id").equals(locator.segmentId())).findFirst().orElseThrow(()->fail(PROVENANCE_UNAVAILABLE));var marks=rows.stream().filter(r->r.table()==Table.TRANSCRIPT_SEGMENT_MARK&&r.string("revision_id").equals(locator.transcriptRevisionId())&&r.string("segment_id").equals(locator.segmentId())).map(r->r.string("mark")).sorted().map(v->(CanonicalValue)string(v)).toList();transcript.add(object(field("sourceId",string(entry.sourceId())),field("segmentId",string(locator.segmentId())),field("body",string(segment.string("body"))),field("marks",new Sequence(marks))));}
  var template=one(rows,Table.TEMPLATE_REVISION,draft.templateRevisionId());require(ControlledMinutesTemplateInstaller.THEMES.equals(template.string("themes"))&&template.number("theme_count")==7,PROFILE_UNAVAILABLE);var themes=Arrays.stream(Category.values()).map(c->(CanonicalValue)string(c.name())).toList();var pinned=draft.elementSetId()==null?List.<CanonicalValue>of():pinned(rows,draft.elementSetId(),binding.catalog(),excluded);
  var manifest=fields(binding.manifest(),"meetingId","inputId","confirmation","segments","batch","materials","template","exclusion","elements","sources","configs","scope","base");var exclusion=fields(manifest.get("exclusion"),"mode","revisionId","revision","contentHash","entries");var entries=new ArrayList<CanonicalValue>();for(var value:array(exclusion.get("entries"))){var item=fields(value,"locatorId","locator","category","reasonHash");var aliases=binding.catalog().sources().stream().filter(s->ContractValues.locator(s.fact().locator()).equals(item.get("locator"))).toList();require(aliases.size()==1,SOURCE_NOT_IN_INPUT);entries.add(object(field("sourceId",string(aliases.getFirst().sourceId())),field("locatorId",item.get("locatorId")),field("category",item.get("category")),field("reasonHash",item.get("reasonHash"))));}
  var background=MaterialMinutesContext.render(rows,binding,excluded);
  var payload=object(field("protocolVersion",model.get("protocolVersion")),field("modelIdentity",model.get("modelIdentity")),field("parameters",model.get("parameters")),field("instructionText",prompt.get("instructionText")),field("inputManifest",binding.manifest()),field("transcript",new Sequence(transcript)),field("template",object(field("revisionId",string(template.string("id"))),field("name",string(template.string("name"))),field("themes",new Sequence(themes)))),field("pinnedElements",object(field("mode",string(draft.elementSetId()==null?"EMPTY":"PINNED")),field("rows",new Sequence(pinned)))),field("exclusions",object(field("revisionId",string(draft.exclusionRevisionId())),field("entries",new Sequence(entries)))));
  if(draft.materialSnapshotId()==null)return payload;var fields=new ArrayList<CanonicalValue.Entry>(payload.entries());fields.add(field("backgroundMaterials",new Sequence(background)));return new CanonicalValue.ObjectValue(fields);
 }
 private static List<CanonicalValue> pinned(List<FullRow> rows,String set,Catalog catalog,Set<CanonicalValue> excluded){
  one(rows,Table.ELEMENT_SET,set);var out=new ArrayList<CanonicalValue>();var elements=rows.stream().filter(r->r.table()==Table.MINUTES_ELEMENT&&r.string("set_id").equals(set)).sorted(Comparator.comparingInt((FullRow r)->Category.valueOf(r.string("category")).ordinal()).thenComparingLong(r->r.number("ordinal"))).toList();
  for(var row:elements){var uses=rows.stream().filter(r->r.table()==Table.EVIDENCE_LINK&&row.string("id").equals(r.nullableString("element_id"))).toList();if(!excluded.isEmpty())require(!uses.isEmpty(),CAPABILITY_UNAVAILABLE);var sources=sources(rows,uses.stream().map(r->r.string("locator_id")).toList(),catalog);if(intersects(sources,catalog,excluded))continue;CanonicalValue action=nil();if(row.string("category").equals("ACTION")){var accepted=rows.stream().filter(r->r.table()==Table.ACTION_ITEM&&row.string("id").equals(r.string("element_id"))).toList();var suggestions=rows.stream().filter(r->r.table()==Table.ACTION_SUGGESTION&&row.string("id").equals(r.string("element_id"))).toList();require(accepted.size()==1&&suggestions.size()<=1,PROVENANCE_UNAVAILABLE);var item=accepted.getFirst();var suggestion=suggestions.isEmpty()?null:suggestions.getFirst();action=object(
    field("ownerEnterpriseId",nullable(item.nullableString("owner_enterprise_id"))),
    field("ownerDisplay",nullable(item.nullableString("owner_display"))),
    field("dueOn",nullable(item.nullableString("due_on"))),
    field("ownerMention",nullable(suggestion==null?null:suggestion.nullableString("owner_mention"))),
    field("suggestedDueOn",nullable(suggestion==null?null:suggestion.nullableString("due_on"))));}
   out.add(object(field("kind",string("ELEMENT")),field("id",string(row.string("id"))),field("category",string(row.string("category"))),field("ordinal",number(row.number("ordinal"))),field("body",string(row.string("body"))),field("supportState",string(row.string("support_state"))),field("action",action),field("sources",aliases(sources))));
  }
  for(var row:rows.stream().filter(r->r.table()==Table.SENSITIVE_DETECTION&&r.string("set_id").equals(set)).sorted(Comparator.comparing((FullRow r)->r.string("category")).thenComparingLong(r->r.number("ordinal"))).toList()){var locators=rows.stream().filter(r->r.table()==Table.SENSITIVE_DETECTION_SOURCE&&r.string("detection_id").equals(row.string("id"))).map(r->r.string("locator_id")).toList();var sources=sources(rows,locators,catalog);if(intersects(sources,catalog,excluded))continue;out.add(object(field("kind",string("SENSITIVE_DETECTION")),field("id",string(row.string("id"))),field("category",string(row.string("category"))),field("ordinal",number(row.number("ordinal"))),field("sources",aliases(sources))));}
  for(var row:rows.stream().filter(r->r.table()==Table.BACKGROUND_NOTE&&r.string("set_id").equals(set)).sorted(Comparator.comparingLong(r->r.number("ordinal"))).toList()){var locators=rows.stream().filter(r->r.table()==Table.BACKGROUND_NOTE_SOURCE&&r.string("note_id").equals(row.string("id"))).map(r->r.string("locator_id")).toList();if(!excluded.isEmpty())require(!locators.isEmpty(),CAPABILITY_UNAVAILABLE);var sources=sources(rows,locators,catalog);if(intersects(sources,catalog,excluded))continue;out.add(object(field("kind",string("BACKGROUND_NOTE")),field("id",string(row.string("id"))),field("ordinal",number(row.number("ordinal"))),field("body",string(row.string("body"))),field("sources",aliases(sources))));}
  return List.copyOf(out);
 }
 private static FullRow one(List<FullRow> rows,Table table,String id){var found=rows.stream().filter(r->r.table()==table&&r.string("id").equals(id)).toList();require(found.size()==1,PROVENANCE_UNAVAILABLE);return found.getFirst();}
 private static CanonicalValue nullable(String value){return value==null?nil():string(value);}
 private static CanonicalValue aliases(List<String> values){return new Sequence(values.stream().map(v->(CanonicalValue)string(v)).toList());}
 private static List<String> sources(List<FullRow> rows,List<String> locators,Catalog catalog){var aliases=new TreeSet<String>(Comparator.comparingLong(ama.contract.MinutesContracts::aliasOrdinal));for(String id:locators){var row=one(rows,Table.SOURCE_LOCATOR,id);var locator=MaterialMinutesContext.locator(row);var matched=catalog.sources().stream().filter(s->s.fact().locator().equals(locator)).toList();require(matched.size()==1,SOURCE_NOT_IN_INPUT);aliases.add(matched.getFirst().sourceId());}return List.copyOf(aliases);}
 private static boolean intersects(List<String> aliases,Catalog catalog,Set<CanonicalValue> excluded){return aliases.stream().anyMatch(alias->excluded.contains(ContractValues.locator(catalog.source(alias).fact().locator())));}
 private static Set<CanonicalValue> excluded(ConfigBindings.ValidatedGenerationBinding binding){var manifest=fields(binding.manifest(),"meetingId","inputId","confirmation","segments","batch","materials","template","exclusion","elements","sources","configs","scope","base");var exclusion=fields(manifest.get("exclusion"),"mode","revisionId","revision","contentHash","entries");var locations=new HashSet<CanonicalValue>();for(var entry:array(exclusion.get("entries")))locations.add(fields(entry,"locatorId","locator","category","reasonHash").get("locator"));return Set.copyOf(locations);}
 public static void rejectExcludedEvidence(ConfigBindings.ValidatedGenerationBinding binding,ValidatedOutput output){var excluded=excluded(binding);for(var evidence:output.output().evidence())for(String alias:evidence.sourceIds().values())require(!excluded.contains(ContractValues.locator(binding.catalog().source(alias).fact().locator())),SOURCE_NOT_IN_INPUT);}
}
